INSERT INTO "public"."ricette" ("pk_ricetta", "titolo", "stampata", "porzioni", "n_porzioni", "tempo_preparazione", "tempo_cottura", "tempo_agg", "fk_cat", "etnica", "data", "immagine", "esecuzione", "diff", "commenti", "cottura", "autore", "voto", "nascosta", "preferita") VALUES
	(838, 'Torta di rose (lm)', true, NULL, NULL, '00:30:00', '00:30:00', '06:00:00', 23, NULL, '2024-09-25', NULL, 'Lavorare in una ciotola la pasta madre con l''acqua, 2 cucchiai di zucchero, il sale, i tuorli. Aggiungere la farina in due o tre volte. Passare sul tavolo e poco alla volta aggiungere 50gr di  burro. Lavorare finché l''impasto è bene amalgamato e liscio. Mettere a riposare per 3 ore in una ciotola unta di burro.
